-- Operational review in synthetic staging only. No commercial rate/deadline activation.
insert into public.business_setting_versions(setting_key,version,value,reason) values('marketplace_seller_terms',1,'{"id": "direct-selling-review-v1", "reviewOnly": true, "commercialApproved": false, "title": {"en": "Direct selling rules — staging review", "fr": "Règles de vente directe — examen en test"}, "rules": [{"id": "listing", "en": "I have the right to sell this actual item. My photos and description accurately show its condition. Unknown details stay unknown.", "fr": "J’ai le droit de vendre cet article réel. Mes photos et ma description montrent fidèlement son état. Les détails inconnus restent inconnus."}, {"id": "defects", "en": "I disclose every known defect in text and provide a clear photo of each defect. Extra angles are optional. Photos do not guarantee authenticity or payout.", "fr": "Je décris chaque défaut connu et fournis une photo nette de chacun. Les angles supplémentaires sont facultatifs. Les photos ne garantissent ni l’authenticité ni le versement."}, {"id": "fulfilment", "en": "I remain responsible for accurate shipping details, packaging and dispatch under the order’s accepted shipping terms. Creating a label is not proof of carrier handoff.", "fr": "Je reste responsable des coordonnées d’expédition, de l’emballage et de l’envoi selon les conditions acceptées de la commande. Créer une étiquette ne prouve pas la remise au transporteur."}, {"id": "payment", "en": "An accepted price offer alone does not charge the buyer. Purchases and seller payments require the secure provider flow; ordinary private messages cannot confirm payment. Fees, tax and deadlines must be shown before a real transaction.", "fr": "L’acceptation d’une offre seule ne débite pas l’acheteur. Les achats et versements exigent le parcours sécurisé du fournisseur; un message privé ne confirme aucun paiement. Frais, taxes et délais doivent être affichés avant une transaction réelle."}, {"id": "disputes", "en": "A buyer can report a missing, wrong, damaged, counterfeit or substantially misdescribed item through the order’s issue flow. Relevant seller proceeds must remain on hold during review. Both parties may provide listing, message, photo and tracking evidence.", "fr": "L’acheteur peut signaler un article manquant, incorrect, endommagé, contrefait ou sensiblement différent par le parcours de problème de la commande. Les revenus concernés restent bloqués pendant l’examen. Les deux parties peuvent fournir annonce, messages, photos et suivi."}, {"id": "returns", "en": "Change of mind or fit, where the declared information is accurate, is assessed separately from misdescription, subject to applicable legal rights. An approved return must specify the address, tracking, deadline, refund components and responsibility for costs.", "fr": "Le changement d’avis ou une taille qui ne convient pas malgré des renseignements exacts se distingue d’une description inexacte, sous réserve des droits légaux. Tout retour approuvé précise adresse, suivi, délai, éléments remboursés et responsabilité des frais."}, {"id": "rights", "en": "SHIKIMOMO reviews transaction issues under its published policy, with human review and a reasoned decision. This does not impose mandatory legal arbitration, waive access to courts or replace statutory rights. Marketing consent is separate and optional.", "fr": "SHIKIMOMO examine les problèmes selon sa politique publiée, avec examen humain et décision motivée. Cela n’impose pas d’arbitrage juridique obligatoire, ne retire pas l’accès aux tribunaux et ne remplace pas les droits légaux. Le consentement publicitaire est distinct et facultatif."}]}'::jsonb,'Versioned staging review of seller responsibilities and issue handling; not a production launch');
create table private.marketplace_terms_acceptances(
 user_id uuid not null references auth.users(id),policy_version integer not null,
 policy_snapshot jsonb not null,locale text not null check(locale in ('en-CA','fr-CA')),
 accepted_at timestamptz not null default now(),primary key(user_id,policy_version)
);
alter table private.marketplace_terms_acceptances enable row level security;
revoke all on private.marketplace_terms_acceptances from public,anon,authenticated,service_role;
create function private.guard_marketplace_terms_acceptance() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Policy acceptance history is immutable';end$$;
revoke all on function private.guard_marketplace_terms_acceptance() from public,anon,authenticated,service_role;
create trigger marketplace_terms_immutable before update or delete on private.marketplace_terms_acceptances for each row execute function private.guard_marketplace_terms_acceptance();
create function public.marketplace_policy_document() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('version',version,'value',value) from public.business_setting_versions where setting_key='marketplace_seller_terms' and effective_at<=now() order by version desc limit 1$$;
revoke all on function public.marketplace_policy_document() from public,anon,authenticated;
grant execute on function public.marketplace_policy_document() to anon,authenticated;
create function public.marketplace_seller_terms_status() returns jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=private.marketplace_require_user();d jsonb;stamp timestamptz;begin
 d:=public.marketplace_policy_document();
 select accepted_at into stamp from private.marketplace_terms_acceptances where user_id=u and policy_version=(d->>'version')::integer and policy_snapshot=d->'value';
 return jsonb_build_object('document',d,'accepted',stamp is not null,'acceptedAt',stamp);end$$;
revoke all on function public.marketplace_seller_terms_status() from public,anon;
grant execute on function public.marketplace_seller_terms_status() to authenticated;
create function public.marketplace_accept_seller_terms(p_version integer,p_locale text,p_accept boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=private.marketplace_require_user();d jsonb;v jsonb;a private.marketplace_terms_acceptances%rowtype;begin
 perform pg_advisory_xact_lock(hashtextextended(u::text,7406));d:=public.marketplace_policy_document();v:=d->'value';
 if p_accept is distinct from true or p_locale is null or p_locale not in ('en-CA','fr-CA') or p_version is distinct from (d->>'version')::integer or v is null then raise exception 'Read and accept the current seller rules';end if;
 if coalesce((v->>'reviewOnly')::boolean,true) then
 if current_database()<>'shikimomo_staging' or to_regprocedure('public.assert_synthetic_staging()') is null then raise exception 'Review-only rules cannot be accepted outside synthetic staging';end if;
 perform public.assert_synthetic_staging();
 elsif coalesce((v->>'commercialApproved')::boolean,false) is not true then raise exception 'Seller rules are not approved';end if;
 select * into a from private.marketplace_terms_acceptances where user_id=u and policy_version=p_version;
 if a.user_id is not null then if a.policy_snapshot<>v then raise exception 'Policy content changed without a new version';end if;return jsonb_build_object('version',p_version,'acceptedAt',a.accepted_at,'commercialEnabled',false);end if;
 insert into private.marketplace_terms_acceptances(user_id,policy_version,policy_snapshot,locale) values(u,p_version,v,p_locale) returning * into a;
 insert into public.audit_logs(admin_user_id,action,entity_type,entity_id,new_value,reason) values(u,'marketplace.seller_rules_accepted','seller_terms',p_version::text,jsonb_build_object('version',p_version,'locale',p_locale,'reviewOnly',v->'reviewOnly'),'Explicit acceptance of the displayed policy version; no bank access, commercial activation or waiver of legal rights');
 return jsonb_build_object('version',p_version,'acceptedAt',a.accepted_at,'commercialEnabled',false);end$$;
revoke all on function public.marketplace_accept_seller_terms(integer,text,boolean) from public,anon;
grant execute on function public.marketplace_accept_seller_terms(integer,text,boolean) to authenticated;
create function private.marketplace_require_seller_terms() returns void language plpgsql stable security definer set search_path='' as $$begin
 if (public.marketplace_seller_terms_status()->>'accepted')::boolean is not true then raise exception 'Accept the current seller rules before requesting review';end if;end$$;
revoke all on function private.marketplace_require_seller_terms() from public,anon,authenticated,service_role;

create or replace function public.marketplace_request_review(p_item uuid,p_version integer) returns void language plpgsql security definer set search_path='' as $$declare u uuid:=private.marketplace_require_user();i public.items%rowtype;begin
 perform private.marketplace_require_seller_terms();
 select * into i from public.items where id=p_item and owner_id=u and sale_mode='peer_to_peer' and status='listing_preparation' for update;
 if i.id is null or i.listing_version is distinct from p_version then raise exception 'Draft changed';end if;
 if not exists(select 1 from private.marketplace_sellers where user_id=u) or not exists(select 1 from public.clothing_listing_evidence e where e.item_id=i.id and e.evidence_source='seller' and e.listing_version=i.listing_version and e.disclosure_version='seller-disclosure-v2') or i.listed_price_cents is null or i.listed_price_cents<800 then raise exception 'Complete profile, price, photos and disclosures first';end if;
 if exists(select 1 from private.marketplace_listing_reviews where item_id=i.id and listing_version=i.listing_version and status in('pending','approved')) then return;end if;
 if exists(select 1 from private.marketplace_listing_reviews where item_id=i.id and listing_version=i.listing_version and status='rejected') then raise exception 'Revise the listing before requesting again';end if;
 insert into private.marketplace_listing_reviews(item_id,listing_version,status) values(i.id,i.listing_version,'pending') on conflict(item_id) do update set listing_version=excluded.listing_version,status='pending',reason=null,requested_at=now(),reviewed_at=null,reviewed_by=null;
 insert into public.audit_logs(admin_user_id,action,entity_type,entity_id,new_value,reason) values(u,'marketplace.review_requested','item',i.id::text,jsonb_build_object('version',i.listing_version),'Content moderation request; no physical inspection or publication');end$$;
